import { signal, type Accessor } from '@vorzelajs/core'
import { For } from '@vorzelajs/dom'
import { accessorOf } from '~/hooks/index.ts'
import { cx } from '~/lib/cx.ts'
import styles from './tab-bar.module.scss'
import type { CSSProperties, KeyboardEvent, ReactNode } from '~/lib/types.ts'

export interface TabBarItem {
  value: string
  label: string
  icon?: ReactNode
  /** Small count or dot rendered above the icon. */
  badge?: ReactNode
  disabled?: boolean
}

export interface TabBarProps {
  items: TabBarItem[]
  value?: string | (() => string)
  defaultValue?: string
  onChange?: (value: string) => void
  /** Accessible name for the navigation landmark. */
  label?: string
  /** `fixed` pins the bar to the bottom with a safe-area inset. */
  position?: 'static' | 'fixed'
  className?: string
}

function reactive<T>(value: () => T): T {
  return value as unknown as T
}

/**
 * Compact bottom navigation. Grid-based, one tab stop, roving focus with
 * Arrow/Home/End keys. Active state is expressed with `aria-current`.
 */
export function TabBar({
  items,
  value: valueProp,
  defaultValue,
  onChange,
  label = 'Primary navigation',
  position = 'static',
  className,
}: TabBarProps) {
  const [internal, setInternal] = signal(
    defaultValue ?? items[0]?.value ?? '',
  )
  const controlled = valueProp === undefined ? null : accessorOf(valueProp)
  const value: Accessor<string> = () =>
    controlled ? controlled() : internal()

  const setValue = (next: string): void => {
    if (!controlled) setInternal(next)
    onChange?.(next)
  }

  const refs: Array<HTMLButtonElement | null> = []
  const enabled = items.filter((item) => !item.disabled)
  const activeIndex = (): number =>
    items.findIndex((item) => item.value === value())
  const tabStop = (): number => (activeIndex() >= 0 ? activeIndex() : 0)

  const move = (direction: 1 | -1): void => {
    if (enabled.length === 0) return
    const currentValue = items[tabStop()]?.value
    const currentEnabled = Math.max(
      0,
      enabled.findIndex((item) => item.value === currentValue),
    )
    const next =
      enabled[(currentEnabled + direction + enabled.length) % enabled.length]
    if (next) {
      setValue(next.value)
      refs[items.indexOf(next)]?.focus()
    }
  }

  const focusValue = (next: TabBarItem | undefined): void => {
    if (!next) return
    setValue(next.value)
    refs[items.indexOf(next)]?.focus()
  }

  const handleKeyDown = (
    event: KeyboardEvent<HTMLButtonElement>,
  ): void => {
    if (event.key === 'ArrowRight') {
      event.preventDefault()
      move(1)
    } else if (event.key === 'ArrowLeft') {
      event.preventDefault()
      move(-1)
    } else if (event.key === 'Home') {
      event.preventDefault()
      focusValue(enabled[0])
    } else if (event.key === 'End') {
      event.preventDefault()
      focusValue(enabled[enabled.length - 1])
    }
  }

  return (
    <nav
      aria-label={label}
      className={cx(styles.root, position === 'fixed' && styles.fixed, className)}
      style={{ '--tab-count': items.length } as CSSProperties}
    >
      <For each={() => items} key={(item) => item.value}>
        {(item, index) => {
          const active = (): boolean => item.value === value()

          return (
            <button
              ref={(node) => {
                refs[index] = node as HTMLButtonElement | null
              }}
              type="button"
              disabled={item.disabled}
              aria-current={() => (active() ? 'page' : undefined)}
              tabIndex={reactive(() => (active() ? 0 : -1))}
              className={reactive(() =>
                cx(styles.item, active() && styles.active),
              )}
              onClick={() => setValue(item.value)}
              onKeyDown={
        handleKeyDown as unknown as (event: globalThis.KeyboardEvent) => void
      }
            >
              {item.icon ? <span className={styles.icon}>{item.icon}</span> : null}
              <span className={styles.label}>{item.label}</span>
              {item.badge ? <span className={styles.badge}>{item.badge}</span> : null}
            </button>
          )
        }}
      </For>
    </nav>
  )
}

@use 'styles' as vz;

.root {
  --tab-count: 4;

  display: grid;
  grid-template-columns: repeat(var(--tab-count), minmax(0, 1fr));
  gap: 2px;
  padding: 5px;
  border: 1px solid vz.color('border', 0.7);
  border-radius: vz.radius('2xl');
  background: vz.color('card', 0.72);
  box-shadow: vz.elevation(2);
  backdrop-filter: blur(20px) saturate(180%);
}

.fixed {
  position: fixed;
  right: vz.space(3);
  bottom: calc(#{vz.space(3)} + env(safe-area-inset-bottom, 0px));
  left: vz.space(3);
  z-index: vz.z('sticky');
  max-width: 32rem;
  margin-inline: auto;
}

.item {
  position: relative;
  display: flex;
  min-width: 0;
  min-height: 3rem;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  padding: vz.space(1) vz.space(1);
  border: 0;
  border-radius: vz.radius('lg');
  background: transparent;
  color: vz.color('muted-foreground');
  font-size: 0.625rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  cursor: pointer;
  transition:
    background-color vz.duration('base') vz.ease('out'),
    color vz.duration('base') vz.ease('out'),
    transform vz.duration('fast') vz.ease('out');

  @include vz.hover {
    color: vz.color('foreground');
  }

  @include vz.active {
    transform: scale(0.97);
  }

  @include vz.focus-ring(2px, -2px, 0.6);

  @include vz.disabled {
    opacity: 0.4;
    pointer-events: none;
  }

  @include vz.motion-reduce {
    transition: none;

    @include vz.active {
      transform: none;
    }
  }
}

.active {
  background: vz.color('primary', 0.12);
  color: vz.color('primary');
}

.icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  svg {
    @include vz.icon(5);
  }
}

.label {
  max-width: 100%;

  @include vz.truncate;
}

.badge {
  position: absolute;
  top: 2px;
  left: 50%;
  display: inline-flex;
  min-width: 1rem;
  height: 1rem;
  align-items: center;
  justify-content: center;
  padding-inline: 4px;
  border: 2px solid vz.color('card');
  border-radius: vz.radius('full');
  background: vz.color('destructive');
  color: vz.color('destructive-foreground');
  font-size: 0.5625rem;
  font-weight: 700;
  line-height: 1;
  transform: translateX(14px);
}

@include vz.up('sm') {
  .item {
    min-height: 3.25rem;
    font-size: 0.6875rem;
  }

  .icon svg {
    width: 1.375rem;
    height: 1.375rem;
  }
}
